\section{Introduction}

\subsection{Motivation}
A recurring pattern in learning theory, symbolic dynamics and constraint satisfaction is the following. One has an infinite family of \emph{behaviours}, each a total function from an enumerated set of queries to a finite answer alphabet; one has a notion of \emph{finite observation}, namely restriction to the first $n$ queries; and one wants to know how the number of distinguishable finite observations grows with $n$.

When the alphabet is $\{\zero,\one\}$ and the query set is $\mathbb N$, the family of all behaviours is $\C=\{\zero,\one\}^{\mathbb N}$, the \emph{truth space}. Its natural geometry is ultrametric: two behaviours are close precisely when no short interrogation distinguishes them. Formalising ``how short'' as a distance gives the first-disagreement metric, whose balls are exactly the observation classes. Under this metric the truth space is compact, and this compactness is the abstract reason why an infinite family is controlled by a sequence of finite ones.

Our aims are twofold: to give a self-contained, constructive development of completeness, total boundedness and compactness of $\C$, with explicit witnesses at every step rather than an appeal to Tychonoff's theorem; and to carry out the same programme for a genuinely constrained subfamily, the golden-mean subshift, computing its covering combinatorics \emph{exactly} rather than up to constants.

\subsection{Results}
The main theorems are: the ball--prefix dictionary (Theorem~\ref{thm:dict}); total boundedness with the explicit truncation net (Theorem~\ref{thm:tb}); completeness by coordinatewise stabilisation (Theorem~\ref{thm:complete}); compactness (Theorem~\ref{thm:compact}); $2$-Lipschitz continuity of the shift (Theorem~\ref{thm:lip}); closedness and compactness of the golden-mean subshift (Theorem~\ref{thm:closed}, Corollary~\ref{cor:compactG}); perfectness (Theorem~\ref{thm:perfect}); the Fibonacci word count (Theorem~\ref{thm:fib}); exact prefix realisation (Theorem~\ref{thm:prefix}); and matched covering and packing at scale $2^{-n}$ (Theorems~\ref{thm:cover} and~\ref{thm:pack}, Corollary~\ref{cor:NP}), from which the box dimension $\log\varphi/\log 2$ and the topological entropy $\log\varphi$ follow.

\subsection{Relation to classical results}
Each ingredient has a classical ancestor: compactness of $\{0,1\}^{\mathbb N}$ is Tychonoff's theorem; closedness and shift invariance is the definition of a subshift; the entropy $\log\varphi$ is the Perron eigenvalue of $A=\begin{psmallmatrix}1&1\\1&0\end{psmallmatrix}$; and Brouwer's theorem characterises the Cantor set. The contribution here is constructive sharpness: every existential statement carries an explicit witness, and the covering number is \emph{computed}, with a matching packing certificate, rather than merely bounded.

\section{The truth space and its ultrametric}

\begin{definition}[Truth space]
Let $\C=\{\zero,\one\}^{\mathbb N}$ be the set of functions $x:\mathbb N\to\{\zero,\one\}$. We write $x_k$ for $x(k)$ and call $x$ a \emph{truth stream}; $x_k$ is the answer to query $k$.
\end{definition}

\begin{definition}[Agreement to depth $n$]
For $n\in\mathbb N$ and $x,y\in\C$, write $x\equiv_n y$ if $x_k=y_k$ for all $k<n$. Note $x\equiv_0y$ always holds, vacuously.
\end{definition}

\begin{definition}[First disagreement and the metric]
For $x\neq y$ set $\fd(x,y)=\min\{k: x_k\neq y_k\}$, and define
\[
d(x,y)=\begin{cases}0,& x=y,\\ 2^{-\fd(x,y)},& x\neq y.\end{cases}
\]
\end{definition}

\begin{proposition}
$d$ is a metric and satisfies the strong triangle inequality $d(x,z)\le\max\bigl(d(x,y),d(y,z)\bigr)$.
\end{proposition}

\begin{proof}[Proof sketch]
Symmetry and nondegeneracy are immediate. Each $\equiv_n$ is an equivalence relation, and $x\equiv_m y$, $y\equiv_n z$ imply $x\equiv_{\min(m,n)}z$. Taking $m=\fd(x,y)$, $n=\fd(y,z)$ gives $\fd(x,z)\ge\min(m,n)$; apply the antitone map $t\mapsto 2^{-t}$.
\end{proof}

\begin{theorem}[Ball--prefix dictionary]\label{thm:dict}
For all $x,y\in\C$ and $n\in\mathbb N$, $d(x,y)\le 2^{-n}$ if and only if $x\equiv_n y$.
\end{theorem}

\begin{proof}[Proof sketch]
If $x=y$ both sides hold. Otherwise $2^{-\fd(x,y)}\le2^{-n}$ iff $\fd(x,y)\ge n$, which by minimality of $\fd$ is exactly agreement on all $k<n$.
\end{proof}

\begin{corollary}\label{cor:strict}
If $d(x,y)<2^{-n}$ then $x\equiv_n y$. Moreover $\diam\C\le 1$, since $x\equiv_0y$ always.
\end{corollary}

Because $d$ takes only the values $0$ and $2^{-n}$, every closed ball is clopen, and two closed balls of equal radius are either identical or disjoint. The depth-$n$ prefix classes partition $\C$ into $2^{n}$ clopen pieces.

\begin{lemma}[Dyadic cofinality]\label{lem:dyadic}
For every $\varepsilon>0$ there is $n\in\mathbb N$ with $2^{-n}<\varepsilon$.
\end{lemma}

\section{Total boundedness}

\begin{definition}[Truncation and net]
For $n\in\mathbb N$ define $T_nx\in\C$ by $(T_nx)_k=x_k$ for $k<n$ and $\zero$ otherwise. For a word $s\in\{\zero,\one\}^n$ let $\iota_n(s)\in\C$ agree with $s$ below $n$ and be $\zero$ above; put $N_n=\iota_n(\{\zero,\one\}^n)$, a set of $2^n$ streams.
\end{definition}

\begin{lemma}\label{lem:trunc}
$T_nx\in N_n$ and $x\equiv_n T_nx$ for every $x\in\C$.
\end{lemma}

\begin{theorem}[Total boundedness]\label{thm:tb}
$(\C,d)$ is totally bounded. Explicitly, if $2^{-n}<\varepsilon$ then the $2^n$ streams of $N_n$ form an $\varepsilon$-net for $\C$.
\end{theorem}

\begin{proof}[Proof sketch]
Given $\varepsilon>0$ choose $n$ by Lemma~\ref{lem:dyadic}. For any $x$, Lemma~\ref{lem:trunc} gives $T_nx\in N_n$ with $x\equiv_nT_nx$, so $d(x,T_nx)\le2^{-n}<\varepsilon$ by Theorem~\ref{thm:dict}.
\end{proof}

The net is optimal: a closed $2^{-n}$-ball is a single prefix class, so any $2^{-n}$-net has at least $2^n$ elements.

\section{Completeness and compactness}

\begin{lemma}[Cauchy implies eventual agreement]\label{lem:cauchy}
If $(u^{(i)})$ is Cauchy in $\C$, then for every $n$ there is $N(n)$ with $u^{(i)}\equiv_n u^{(j)}$ whenever $i,j\ge N(n)$.
\end{lemma}

\begin{proof}[Proof sketch]
Apply the Cauchy criterion with $\varepsilon=2^{-n}$ and then Corollary~\ref{cor:strict}.
\end{proof}

\begin{theorem}[Completeness]\label{thm:complete}
$(\C,d)$ is complete. With $N(\cdot)$ as above, the limit of $(u^{(i)})$ is the diagonal read-off
\[
u^{\star}_k=u^{(N(k+1))}_k .
\]
\end{theorem}

\begin{proof}[Proof sketch]
We claim $u^{(i)}\equiv_n u^{\star}$ for all $i\ge N(n)$. Fix $k<n$ and put $m=\max(i,N(k+1))$. Since $i,m\ge N(n)$, Lemma~\ref{lem:cauchy} at depth $n$ gives $u^{(i)}_k=u^{(m)}_k$; since $m,N(k+1)\ge N(k+1)$, the same lemma at depth $k+1$ gives $u^{(m)}_k=u^{(N(k+1))}_k=u^\star_k$. Chaining proves the claim. Given $\varepsilon>0$, choose $n$ with $2^{-n}<\varepsilon$; then $d(u^{(i)},u^\star)\le2^{-n}<\varepsilon$ for $i\ge N(n)$ by Theorem~\ref{thm:dict}.
\end{proof}

The reconciliation of the two freezing times through the index $m$ is the crux of the diagonal argument.

\begin{theorem}[Compactness]\label{thm:compact}
$(\C,d)$ is a compact metric space.
\end{theorem}

\begin{proof}[Proof sketch]
A metric space is compact iff complete and totally bounded; combine Theorems~\ref{thm:tb} and~\ref{thm:complete}.
\end{proof}

\begin{remark}
The metric route makes compactness quantitative: the $\varepsilon$-covering number of $\C$ equals $2^{\lceil\log_2(1/\varepsilon)\rceil}$.
\end{remark}

\section{The shift map}

\begin{definition}
The shift $\sigma:\C\to\C$ is $(\sigma x)_k=x_{k+1}$.
\end{definition}

\begin{lemma}[Splitting agreement]\label{lem:split}
$x\equiv_{n+1}y$ if and only if $x_0=y_0$ and $\sigma x\equiv_n\sigma y$.
\end{lemma}

\begin{theorem}[The shift is $2$-Lipschitz]\label{thm:lip}
$d(\sigma x,\sigma y)\le 2\,d(x,y)$; in particular $\sigma$ is continuous.
\end{theorem}

\begin{proof}[Proof sketch]
Assume $x\neq y$ and write $m=\fd(x,y)$. If $m=0$ then $d(x,y)=1$ and $d(\sigma x,\sigma y)\le1\le2$. If $m=r+1$ then $x\equiv_{r+1}y$, so $\sigma x\equiv_r\sigma y$ by Lemma~\ref{lem:split}, giving $d(\sigma x,\sigma y)\le2^{-r}=2\cdot2^{-(r+1)}=2\,d(x,y)$.
\end{proof}

The constant is sharp: for $x=\zero\one\overline{\zero}$ and $y=\zero\zero\overline{\zero}$ one has $d(x,y)=1/2$ and $d(\sigma x,\sigma y)=1$.

\section{The golden-mean subshift}

\begin{definition}
$\G=\{x\in\C:\ \neg(x_k=\one\wedge x_{k+1}=\one)\ \text{for all }k\}$, the set of streams avoiding the block $\one\one$. It is the subshift of finite type with transition matrix $A=\begin{psmallmatrix}1&1\\1&0\end{psmallmatrix}$.
\end{definition}

\begin{proposition}
The constant stream $\overline{\zero}$ lies in $\G$, so $\G\neq\emptyset$.
\end{proposition}

\begin{theorem}[Closedness]\label{thm:closed}
$\G$ is closed in $\C$.
\end{theorem}

\begin{proof}[Proof sketch]
Let $x\notin\G$, witnessed by $x_k=x_{k+1}=\one$. Put $r=2^{-(k+2)}$. Any $y$ with $d(x,y)<r$ satisfies $x\equiv_{k+2}y$ by Corollary~\ref{cor:strict}, so $y_k=y_{k+1}=\one$ and $y\notin\G$. Thus the complement is open.
\end{proof}

The mechanism is general: a constraint that is a conjunction, over all positions, of predicates depending on finitely many coordinates defines a closed set, since a violation is finitely witnessed and therefore stable.

\begin{corollary}\label{cor:compactG}
$\G$ is compact, being closed in the compact space $\C$.
\end{corollary}

\begin{proposition}[Shift invariance]
$\sigma(\G)\subseteq\G$. Hence $(\G,\sigma)$ is a compact dynamical system with continuous map.
\end{proposition}

\subsection{Perfectness}

\begin{definition}[Spiked truncation]
For $n\in\mathbb N$ define $S_nx\in\C$ by $(S_nx)_k=x_k$ for $k<n$, $(S_nx)_{n+1}=\one$, and $(S_nx)_k=\zero$ otherwise.
\end{definition}

\begin{lemma}\label{lem:trspike}
If $x\in\G$ then $T_nx\in\G$ and $S_nx\in\G$. Moreover $T_nx\neq S_nx$ (they differ at coordinate $n+1$), and $x\equiv_nT_nx$, $x\equiv_nS_nx$.
\end{lemma}

\begin{proof}[Proof sketch]
For $T_n$: two adjacent $\one$s in $T_nx$ must both lie below $n$, hence come from $x$. For $S_n$: an adjacent pair of $\one$s either lies below $n$ (from $x$), or straddles $n$ --- impossible since $(S_nx)_n=\zero$ --- or begins at $k\ge n$, forcing $k=n+1$, while $(S_nx)_{n+2}=\zero$.
\end{proof}

\begin{theorem}[Perfectness]\label{thm:perfect}
For every $x\in\G$ and $\varepsilon>0$ there is $y\in\G$ with $y\neq x$ and $d(x,y)<\varepsilon$. Hence $\G$ has no isolated points.
\end{theorem}

\begin{proof}[Proof sketch]
Choose $n$ with $2^{-n}<\varepsilon$. If $T_nx\neq x$ take $y=T_nx$; otherwise take $y=S_nx$, which differs from $x=T_nx$ by Lemma~\ref{lem:trspike}. In both cases $y\in\G$ and $d(x,y)\le2^{-n}<\varepsilon$.
\end{proof}

\begin{corollary}[Brouwer package]\label{cor:brouwer}
$\G$ is nonempty, compact, perfect and totally disconnected (all balls are clopen), hence homeomorphic to the Cantor set, and in particular to $\C$ itself.
\end{corollary}

\section{Exact covering combinatorics}

\begin{definition}[Admissible words]
A finite word over $\{\zero,\one\}$ is \emph{admissible} if it has no factor $\one\one$. Let $\A_n$ be the set of admissible words of length $n$ and $A_n=|\A_n|$.
\end{definition}

\begin{definition}[Recursive family]
$W_0=\{\varepsilon\}$, $W_1=\{\zero,\one\}$, and $W_{n+2}=\zero\cdot W_{n+1}\ \sqcup\ \one\zero\cdot W_n$.
\end{definition}

\begin{theorem}\label{thm:rec}
$W_n=\A_n$ for all $n$.
\end{theorem}

\begin{proof}[Proof sketch]
Induction. Inclusion $\subseteq$ holds because prefixing an admissible word by $\zero$, or by $\one\zero$, preserves admissibility. Conversely, an admissible $w=b\,r$ of length $n+2$ either has $b=\zero$, in which case $r$ is admissible of length $n+1$; or $b=\one$, in which case the next letter is forced to be $\zero$ and the remaining suffix is admissible of length $n$.
\end{proof}

\begin{theorem}[Fibonacci count]\label{thm:fib}
$A_n=F_{n+2}$, where $F_0=0$, $F_1=1$, $F_{k+2}=F_{k+1}+F_k$. Thus $A_0,A_1,A_2,\dots=1,2,3,5,8,13,21,34,\dots$
\end{theorem}

\begin{proof}[Proof sketch]
The two families of Theorem~\ref{thm:rec} are disjoint (they differ in the first letter) and each prefixing map is injective, so $A_{n+2}=A_{n+1}+A_n$ with $A_0=1=F_2$, $A_1=2=F_3$.
\end{proof}

\begin{definition}[Prefix map and padding]
$\pi_0(x)=\varepsilon$ and $\pi_{n+1}(x)=x_0\cdot\pi_n(\sigma x)$, so $|\pi_n(x)|=n$. For a finite word $w$ let $\widehat w\in\C$ agree with $w$ below $|w|$ and be $\zero$ above.
\end{definition}

\begin{lemma}[Prefixes separate at scale $2^{-n}$]\label{lem:sep}
$\pi_n(x)=\pi_n(y)$ iff $x\equiv_ny$; equivalently $d(x,y)\le2^{-n}$ iff $\pi_n(x)=\pi_n(y)$.
\end{lemma}

\begin{proof}[Proof sketch]
Induction on $n$ using $\pi_{n+1}(x)=x_0\cdot\pi_n(\sigma x)$, injectivity of cons, and Lemma~\ref{lem:split}; then Theorem~\ref{thm:dict}.
\end{proof}

\begin{lemma}\label{lem:padding}
If $x\in\G$ then $\pi_n(x)\in\A_n$. If $w\in\A_n$ then $\widehat w\in\G$. In all cases $\pi_{|w|}(\widehat w)=w$.
\end{lemma}

\begin{proof}[Proof sketch]
The first claim is an induction using $\sigma x\in\G$ and the fact that $\neg(x_0=x_1=\one)$ lets one prepend $x_0$ to an admissible word beginning with $x_1$. The second is an induction on $w$: the pair at index $0$ is admissible by hypothesis, and later pairs come from the tail. The third is an induction using $\sigma(\widehat{b w})=\widehat w$.
\end{proof}

\begin{theorem}[Exact prefix realisation]\label{thm:prefix}
$\pi_n(\G)=\A_n$ for every $n$; hence $|\pi_n(\G)|=F_{n+2}$.
\end{theorem}

\begin{proof}[Proof sketch]
Both inclusions are in Lemma~\ref{lem:padding}: prefixes of admissible streams are admissible, and every admissible word is realised by its zero-padding. Cardinality is Theorem~\ref{thm:fib}.
\end{proof}

\begin{theorem}[Optimal covering]\label{thm:cover}
$\displaystyle \G\subseteq\bigcup_{w\in\A_n}\overline B\bigl(\widehat w,2^{-n}\bigr)$, a union of exactly $F_{n+2}$ closed balls whose centres lie in $\G$.
\end{theorem}

\begin{proof}[Proof sketch]
For $x\in\G$ set $w=\pi_n(x)\in\A_n$; then $\pi_n(\widehat w)=w=\pi_n(x)$, so $d(x,\widehat w)\le2^{-n}$ by Lemma~\ref{lem:sep}.
\end{proof}

\begin{theorem}[Matching packing]\label{thm:pack}
If $v,w\in\A_n$ and $v\neq w$ then $d(\widehat v,\widehat w)>2^{-n}$.
\end{theorem}

\begin{proof}[Proof sketch]
Otherwise $\pi_n(\widehat v)=\pi_n(\widehat w)$ by Lemma~\ref{lem:sep}, i.e.\ $v=w$.
\end{proof}

\begin{corollary}[Covering equals packing]\label{cor:NP}
Let $N(\G,\varepsilon)$ be the minimal number of closed $\varepsilon$-balls covering $\G$ and $P(\G,\varepsilon)$ the maximal size of an $\varepsilon$-separated subset of $\G$. Then
\[
N(\G,2^{-n})=P(\G,2^{-n})=F_{n+2}\qquad\text{for all }n .
\]
\end{corollary}

\begin{proof}[Proof sketch]
Theorem~\ref{thm:cover} gives $N\le F_{n+2}$ and Theorem~\ref{thm:pack} gives $P\ge F_{n+2}$. Conversely a closed $2^{-n}$-ball is a single prefix class, so it contains at most one point of a separated set ($P\le N$), and a cover must meet all $F_{n+2}$ nonempty prefix classes of $\G$ ($N\ge F_{n+2}$) by Theorem~\ref{thm:prefix}.
\end{proof}

\begin{theorem}[Box dimension]\label{thm:dim}
With $\varphi=(1+\sqrt5)/2$,
\[
\dim_{\mathrm B}\G=\lim_{n\to\infty}\frac{\log N(\G,2^{-n})}{n\log 2}=\frac{\log\varphi}{\log2}=0.6942419\ldots
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Corollary~\ref{cor:NP} the numerator is $\log F_{n+2}$, and $\varphi^{\,n}\le F_{n+2}\le\varphi^{\,n+1}$ by induction from $\varphi^2=\varphi+1$. Both resulting bounds converge to $\log\varphi/\log2$.
\end{proof}

\begin{corollary}[Topological entropy]
$h_{\mathrm{top}}(\sigma|_\G)=\lim_n n^{-1}\log A_n=\log\varphi=0.4812\ldots<\log2$. Equivalently the per-symbol capacity of the constraint is $\log_2\varphi\approx0.6942$ bits, against $1$ bit for the unconstrained space.
\end{corollary}

\section{Topological coincidence versus metric and dynamical difference}

Three statements must be held simultaneously.

\smallskip\noindent\textbf{(a) Metrically, $\G$ is strictly thinner.} $\dim_{\mathrm B}\G=\log_2\varphi<1=\dim_{\mathrm B}\C$ by Theorem~\ref{thm:dim}; in particular $\G$ is null for the Bernoulli$(1/2)$ measure on $\C$.

\smallskip\noindent\textbf{(b) Topologically, they are the same space.} By Corollary~\ref{cor:brouwer} both are Cantor sets, hence homeomorphic. An explicit homeomorphism $\C\to\G$ is the \emph{golden substitution}, which reads the source stream letter by letter and emits
\[
\zero\longmapsto\zero,\qquad \one\longmapsto\one\zero,
\]
automatically interposing the spacer that makes $\one\one$ impossible. It is injective (a $\one$ always begins a block, so images are uniquely decodable), surjective onto $\G$ (parse greedily), and bi-continuous (a depth-$n$ input prefix determines an output prefix of length between $n$ and $2n$, and conversely). The dimension deficit is therefore \emph{not} a topological invariant: it is an artefact of the ruler.

\smallskip\noindent\textbf{(c) Dynamically, they are rigidly different.} Fixed-point counts are conjugacy invariants. The full shift has two fixed points, $\overline\zero$ and $\overline\one$; the golden-mean shift has one, since $\overline\one$ is forbidden. As $1\neq2$, no shift-equivariant homeomorphism exists. Period-$2$ points give the next obstruction, $3$ versus $4$; in general the period-$p$ counts of the golden-mean shift are the Lucas numbers $L_p=\tr A^{p}$, against $2^p$ for the full shift.

Same shape, different ruler, different motion.

\section{Algorithms}

\subsection{Admissible-word enumeration}
The recursion $W_{n+2}=\zero\cdot W_{n+1}\sqcup\one\zero\cdot W_n$ enumerates $\A_n$ with no rejection and no duplicates, emitting each of the $F_{n+2}$ words exactly once; time $\Theta(n\varphi^{\,n})$, space $O(n)$ if streamed. The count alone costs $O(n)$ additions, or $O(\log n)$ big-integer multiplications by fast powering of $A$, using $A^{n}=\begin{psmallmatrix}F_{n+1}&F_n\\F_n&F_{n-1}\end{psmallmatrix}$.

\subsection{Metric evaluation and nets}
Evaluating $d(x,y)$ reduces to scanning for the first disagreement; for eventually periodic streams this terminates in time proportional to pre-period plus period. The optimal $2^{-n}$-net of $\G$ is the zero-padding of the enumeration above.

\subsection{Diagonal limit extraction}
Given a Cauchy sequence with modulus $N(\cdot)$, the limit is computed coordinatewise by $u^\star_k=u^{(N(k+1))}_k$: one evaluation per coordinate, $n$ evaluations for a depth-$n$ prefix. This is the algorithmic content of Theorem~\ref{thm:complete}.

\subsection{Closedness certificates}
If $x\notin\G$, a scan finds a witness index $k$ in finite time, and the proof of Theorem~\ref{thm:closed} emits the radius certificate $r=2^{-(k+2)}$ guaranteeing that $B(x,r)$ misses $\G$ entirely.

\subsection{Greedy decoding of the golden substitution}
Scan left to right: on $\zero$ emit $\zero$ and advance one; on $\one$ emit $\one$ and advance two (the next letter is necessarily $\zero$). Linear time, one pass, no backtracking --- the code is uniquely decodable precisely because $\one\one$ is forbidden.

\section{Applications}

\subsection{Constrained hypothesis classes}
Read a truth stream as the behaviour of a total binary predictor on an enumerated query sequence. The unconstrained class has $2^n$ distinguishable depth-$n$ behaviours; the golden-mean class has $F_{n+2}\sim\varphi^{\,n+1}/\sqrt5$. The class therefore loses about $0.306\,n$ bits of expressive capacity by depth $n$, and because Corollary~\ref{cor:NP} is an equality the associated metric-entropy quantities carry no unspecified constants. Compactness is what makes such a class analytically tractable: any infinite family of behaviours has a convergent subsequence, and any continuous risk functional attains its infimum.

\subsection{Online prediction}
The forecaster that always answers $\zero$ makes at most $\lceil n/2\rceil$ mistakes in $n$ rounds against every admissible stream, since $2\,\#\{k<n:x_k=\one\}\le n+1$, with equality for the alternating stream $\overline{\one\zero}$. Conversely an adversary forces $\lfloor n/2\rfloor$ mistakes against any deterministic forecaster, by answering $\one$ whenever the forecaster says $\zero$ and the constraint permits. The minimax mistake rate is exactly $1/2$ per round.

\subsection{Run-length-limited codes}
The golden-mean constraint is the $(d,k)=(1,\infty)$ run-length-limited constraint of magnetic and optical recording. Its Shannon capacity is $\log_2\varphi\approx0.6942$ bits per cell, and at finite blocklength Theorem~\ref{thm:prefix} makes this exact: a rate-$R$ block code of length $n$ exists iff $2^{nR}\le F_{n+2}$.

\subsection{Hard-square models and quasicrystals}
$\G$ is the configuration space of a one-dimensional hard-core lattice gas with nearest-neighbour exclusion, whose infinite-temperature partition function of length $n$ is $F_{n+2}$. The golden substitution of \S8(b) is the Fibonacci substitution generating the canonical one-dimensional quasicrystal.

\section{Discussion}

\subsection{Why exactness is worth the trouble}
Dimension computations usually need only $N(\varepsilon)=\varepsilon^{-s+o(1)}$. Here we get an exact integer with a matching lower-bound certificate at every dyadic scale. Three benefits follow: finite-blocklength coding statements become exact; covering and packing numbers agree (unusual in general, and here a consequence of the ultrametric partition of balls); and the whole hierarchy of counting invariants becomes computable and comparable, which is what lets the dynamical rigidity be detected.

\subsection{The role of the ultrametric}
Every proof above is shorter than its Euclidean analogue for the same reason: $\equiv_n$ is an equivalence relation whose classes are the closed $2^{-n}$-balls. Total boundedness becomes ``there are $2^n$ classes''; completeness becomes ``Cauchy means the class eventually stops changing''; closedness of $\G$ becomes ``a violation lives in one class''; covering equals packing becomes ``classes are disjoint''. The ultrametric is the correct model of finite interrogation, in which all an observer can ever learn is which class a point lies in.

\subsection{Limitations and generality}
The word-count recursion is special to the single forbidden block $\one\one$, but the covering-equals-packing identity is not: for any subshift $X$ over a finite alphabet $\Sigma$ with the first-disagreement metric, $N(X,|\Sigma|^{-n})=P(X,|\Sigma|^{-n})=|\mathcal L_n(X)|$, the number of length-$n$ words of its language, which for a subshift of finite type grows at the Perron rate of the transition matrix. What is special about the golden-mean case is that this number is a Fibonacci number, available in closed form. Measures --- the Parry measure, its Hausdorff normalisation, the multifractal spectrum --- are outside the present scope.

\section{Future directions}

\begin{itemize}
\item \emph{Discrete distance spectrum and dimension.} The distance function takes values in a discrete set, so cylinders are clopen and the space is totally separated; the subshift is uncountable and nowhere dense; the sandwich $\varphi^{\,n}\le F_{n+2}\le\varphi^{\,n+1}$ yields box dimension $\log\varphi/\log2$.
\item \emph{Explicit homeomorphism.} The golden substitution $\zero\mapsto\zero$, $\one\mapsto\one\zero$ is a homeomorphism from the full truth space onto the subshift: the smaller box dimension is invisible to the topology.
\item \emph{Languages and closed sets.} Prefix conditions are clopen, so a prefix language always defines a closed set, and conversely a closed set is recovered from its prefix language. A K\"onig-lemma argument realises every extendable language by infinite streams.
\item \emph{Devaney chaos.} Gluing two admissible words with a single spacer letter yields dense periodic points, topological transitivity, and sensitive dependence with the maximal sensitivity constant $1$.
\item \emph{Entropy and Fekete inequalities.} The same gluing map, with closure under factors, gives combinatorial proofs of $F_{n+2}F_{m+2}\le F_{n+m+3}$ and $F_{n+m+2}\le F_{n+2}F_{m+2}$; exponential sparseness $A_n<2^n$; the entropy gap $\log\varphi<\log2$; and the sharp density bound $2\,\#\{\text{ones}\}\le n+1$, attained by the alternating word.
\item \emph{Minimax online mistake bound.} The all-$\zero$ predictor errs at most $(n+1)/2$ times against every admissible stream, and an explicit adversary forces at least $n/2$ mistakes against every deterministic predictor.
\item \emph{Dynamical rigidity.} The full shift has two fixed points and the golden-mean shift one, so no shift-equivariant bijection exists; the golden-mean shift is surjective but not injective.
\item \emph{Explicit transitive point.} The concatenation of all admissible words separated by buffer letters has dense forward orbit, upgrading transitivity to its strongest classical form; yet the subshift is not minimal.
\item \emph{Beyond.} Period-$p$ counts as Lucas numbers and the zeta function $\zeta(t)=1/\det(I-tA)$; the Parry measure and multifractal analysis; general subshifts of finite type and sofic shifts; and quantitative learning-theoretic consequences of exact covering numbers.
\end{itemize}

\section{Conclusion}

The space of infinite yes/no answer streams, metrised by first disagreement, is a compact ultrametric space whose closed balls are exactly the finite-interrogation classes. Completeness holds because Cauchy sequences freeze coordinatewise; total boundedness because there are only $2^n$ prefixes of length $n$. Imposing the local rule ``never two consecutive yeses'' carves out a closed, hence compact, shift-invariant, perfect subset --- a Cantor set in its own right --- whose finite-scale geometry is known exactly: $F_{n+2}$ balls of radius $2^{-n}$ cover it, $F_{n+2}$ of its points are pairwise farther apart than $2^{-n}$, and these numbers match. The growth rate $\varphi$ of that count is simultaneously the box-dimension exponent, the topological entropy, and the coding capacity of the constraint. The topology sees none of this; the metric sees a $30.6\%$ dimension deficit; the dynamics sees an unbridgeable rigidity.

