ADMISSIBLE-WORDS(n):
  if n = 0: return { empty word }
  if n = 1: return { (0), (1) }
  prev2 <- { empty word }            // = A_0
  prev1 <- { (0), (1) }              // = A_1
  for k <- 2 to n:
      cur <- {}
      for w in prev1:  cur <- cur + { 0 :: w }       // first letter 0, rest free
      for w in prev2:  cur <- cur + { 1 :: 0 :: w }  // first letter 1 forces a 0
      (prev2, prev1) <- (prev1, cur)
  return prev1
  // invariant: |prev1| = F_{k+2}, all elements distinct, all 11-free

COVERING-NUMBER(n):                 // = PACKING-NUMBER(n) at scale 2^-n
  return FIB-FAST(n + 2)

FIB-FAST(n):                        // O(log n) big-integer multiplications
  R <- identity 2x2 ; B <- [[1,1],[1,0]] ; k <- n
  while k > 0:
      if k is odd: R <- R * B
      B <- B * B ; k <- floor(k / 2)
  return R[0][1]

DIAGONAL-LIMIT(terms, modulus):
  // terms(i)   : the i-th stream of a Cauchy sequence
  // modulus(n) : an index N(n) beyond which all terms agree to depth n
  return the stream  k  |->  terms(modulus(k + 1)) (k)

LIMIT-PREFIX(terms, modulus, n):
  out <- empty list
  for k <- 0 to n - 1:
      out.append( terms(modulus(k + 1)) (k) )
  return out

// Correctness.  Fix n and i >= N(n), and let k < n.  Put m = max(i, N(k+1)).
//   (1) i, m >= N(n)      and k < n     ==>  u^(i)_k = u^(m)_k
//   (2) m, N(k+1) >= N(k+1) and k < k+1 ==>  u^(m)_k = u^(N(k+1))_k = u*_k
// Hence u^(i) agrees with u* to depth n, i.e. d(u^(i), u*) <= 2^-n.

BUILD-NET(n):
  return ADMISSIBLE-WORDS(n)          // F_{n+2} centres, each padded with 0s

ASSIGN-TO-BALL(x, n):                 // x an admissible stream
  return PREFIX(x, n)                 // the unique centre within 2^-n of x

PACKING-CERTIFICATE(n):
  C <- { PAD(w) : w in BUILD-NET(n) }
  s <- min over distinct p, q in C of DIST(p, q)
  assert s > 2^-n                     // no ball of radius 2^-n holds two centres
  return (|C|, s)

// Conclusion:  N(G, 2^-n) <= |C| = F_{n+2}  (cover)
//              P(G, 2^-n) >= |C| = F_{n+2}  (packing)
//              P <= N  (balls are prefix classes)  ==>  N = P = F_{n+2}.

algorithms.code:
"""Optimal dyadic net construction with a matched packing certificate.

Given a resolution 2^-n, this builds the canonical cover of the golden-mean
subshift by F_{n+2} closed balls of radius 2^-n, and simultaneously certifies
that no smaller cover exists, by exhibiting the ball centres themselves as a
2^-n-separated subset of the subshift.

The certificate is exact rather than asymptotic: covering number = packing
number = F_{n+2} at every dyadic scale, because closed 2^-n balls are exactly
the depth-n prefix classes and hence partition the space.
"""

from __future__ import annotations

from typing import Callable, List, Sequence, Tuple

Stream = Callable[[int], int]
Word = Tuple[int, ...]


def admissible_words(n: int) -> List[Word]:
    """The 11-free words of length n (there are F_{n+2} of them)."""
    if n == 0:
        return [()]
    if n == 1:
        return [(0,), (1,)]
    prev2: List[Word] = [()]
    prev1: List[Word] = [(0,), (1,)]
    for _ in range(2, n + 1):
        cur: List[Word] = [(0,) + w for w in prev1]
        cur.extend((1, 0) + w for w in prev2)
        prev2, prev1 = prev1, cur
    return prev1


def pad(w: Sequence[int]) -> Stream:
    """Zero-padding: the stream that follows w and answers 0 forever after."""
    ww = tuple(w)
    return lambda k: ww[k] if k < len(ww) else 0


def prefix(x: Stream, n: int) -> Word:
    return tuple(x(k) for k in range(n))


def dist(x: Stream, y: Stream, depth: int = 64) -> float:
    for k in range(depth):
        if x(k) != y(k):
            return 2.0 ** (-k)
    return 0.0


def build_net(n: int) -> List[Word]:
    """The F_{n+2} centres of the optimal 2^-n net of the subshift."""
    return admissible_words(n)


def assign_to_ball(x: Stream, n: int) -> Word:
    """The unique net centre within 2^-n of an admissible stream x: its prefix."""
    return prefix(x, n)


def packing_certificate(n: int) -> Tuple[int, float]:
    """Return (size, minimum pairwise distance) of the separated set of centres.

    The minimum pairwise distance is guaranteed to exceed 2^-n, which certifies
    that no cover by fewer balls of radius 2^-n can exist.
    """
    centres = [pad(w) for w in build_net(n)]
    best = 1.0
    for i in range(len(centres)):
        for j in range(i + 1, len(centres)):
            best = min(best, dist(centres[i], centres[j]))
    return len(centres), best


if __name__ == "__main__":
    print("  n   |net| = F_(n+2)   min pairwise dist   2^-n        strictly larger?")
    print("  ---------------------------------------------------------------------")
    for n in range(1, 11):
        size, sep = packing_certificate(n)
        print(
            f"  {n:2d}   {size:15d}   {sep:17.9f}   {2.0**-n:.9f}   {sep > 2.0**-n}"
        )
    print("\nCover and packing have the same cardinality, so the covering number")
    print("of the golden-mean subshift at scale 2^-n is exactly F_(n+2).")

