ENCODE(w):                            // w an arbitrary binary word
  out <- empty list
  for b in w:
      if b = 0: out.append(0)
      else:     out.append(1); out.append(0)
  return out                          // |out| = |w| + #ones(w),  in [|w|, 2|w|]

DECODE(v):                            // v an admissible word
  out <- empty list ; i <- 0
  while i < |v|:
      if v[i] = 0:
          out.append(0) ; i <- i + 1
      else:
          if i + 1 < |v| and v[i+1] != 0: raise 'forbidden block 11'
          out.append(1) ; i <- i + 2   // the forced 0 is consumed
  return out

// DECODE(ENCODE(w)) = w for every w, and ENCODE(w) is always 11-free.
